const staleAuthError=value=>value==='Please sign in to continue.';
function Notice({children,error=false,focusRef,tabIndex}){const [hidden,setHidden]=useState(false);useEffect(()=>{setHidden(false)},[children,error]);useEffect(()=>{const restore=()=>{if(error&&staleAuthError(children))setHidden(true)},expired=()=>setHidden(false);window.addEventListener('session-restored',restore);window.addEventListener('session-expired',expired);return()=>{window.removeEventListener('session-restored',restore);window.removeEventListener('session-expired',expired)}},[children,error]);return children&&!hidden?<div ref={focusRef} tabIndex={tabIndex} className={`notice ${error?'error':''}`} role={error?'alert':'status'}>{children}</div>:null}
