const focusRecovered=()=>requestAnimationFrame(()=>(document.getElementById('main')||document.querySelector('.initial button'))?.focus());
function useResource(path){const [data,setData]=useState(null),[error,setError]=useState(''),[tick,setTick]=useState(0);const previous=useRef(path),focus=useRef(false);useEffect(()=>{let live=true,restoreFocus=focus.current;focus.current=false;if(previous.current!==path){setData(null);previous.current=path}setError('');if(path)api(path).then(d=>live&&setData(d)).catch(e=>live&&setError(e.message)).finally(()=>live&&restoreFocus&&focusRecovered());return()=>{live=false}},[path,tick]);useEffect(()=>{const restore=()=>{setError(value=>staleAuthError(value)?'':value);setTick(t=>t+1)};window.addEventListener('session-restored',restore);return()=>window.removeEventListener('session-restored',restore)},[]);return {data,error,setData,reload:(restoreFocus=false)=>{focus.current=restoreFocus===true;setTick(t=>t+1)}};}
