function SectionTitle({title,children,back}){return <div className="section-title">{back&&<a className="back" href={back}>Back to book</a>}<h1>{title}</h1>{children}</div>}
function Modal({title,children,onClose}){const ref=useRef(),titleId=useId();useEffect(()=>{const previous=document.activeElement,el=ref.current;[...document.querySelectorAll('dialog[open]')].forEach(dialog=>dialog.setAttribute('aria-hidden','true'));el.showModal();return()=>{el.close();const open=[...document.querySelectorAll('dialog[open]')],top=open.at(-1);top?.removeAttribute('aria-hidden');if(top){if(previous?.isConnected&&top.contains(previous))previous.focus();else top.querySelector('[autofocus],button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')?.focus()}else previous?.focus?.()}},[]);return <dialog ref={ref} aria-modal="true" aria-labelledby={titleId} onCancel={e=>{e.preventDefault();onClose()}} onClick={e=>e.target===ref.current&&onClose()}><div className="dialog-head"><h2 id={titleId}>{title}</h2><button className="icon-button" aria-label="Close dialog" onClick={onClose}><Icon name="close"/></button></div>{children}</dialog>}
function Gate({placement=true,children}){const {boot}=useApp();if(!boot.user)return <div className="gate"><Icon/><h2>Make this reading journey yours</h2><p>Create an account to save progress and practice. You can explore the book right now.</p><LinkButton to="#/auth/register">Create account</LinkButton><a href="#/auth/login">Already have an account? Sign in</a></div>;if(!boot.user.verified)return <Verify/>;if(placement&&boot.onboarding.status!=='complete')return <div className="gate"><h2>Find your starting point</h2><p>A short Spanish check helps choose what to teach and what to refresh. Your place is saved as you go.</p><LinkButton to="#/placement">{boot.onboarding.status==='in_progress'?'Continue your check':'Find my starting point'}</LinkButton><p className="muted">Reading is always available.</p></div>;return children;}
