function Library(){const {boot}=useApp();const [filter,setFilter]=useState('');const books=boot.books.filter(b=>`${b.title} ${b.author}`.toLowerCase().includes(filter.toLowerCase()));return <><section className="hero"><div className="hero-copy"><div className="intro-mark"><span/>Spanish, one passage at a time</div><h1>A book you want to read.<br/>The Spanish to read it.</h1><p>Start with a story. Learn the words and ideas that open it up. Then discover how much you can read on your own.</p><div className="actions"><LinkButton to={boot.user?'#/upload':'#/auth/register'}>{boot.user?'Bring your own PDF':'Start my reading journey'}<Icon name="arrow" size={18}/></LinkButton><a className="text-link" href={href('reader','don-quixote')}>Explore Don Quixote</a></div><p className="hero-note">Short lessons. Your pace. Your next page.</p></div><div className="hero-book" aria-label="An invitation to read Don Quixote"><div className="book-cover"><div className="cover-small">Miguel de Cervantes</div><div className="cover-title">Don<br/>Quijote<br/><span>de la Mancha</span></div><svg className="windmill" viewBox="0 0 220 180" fill="none" aria-hidden="true"><path d="M86 166h59l-8-86-22-20-22 20zM115 93l-9 73M102 119h27M100 140h33"/><path d="m114 81-53-58-15 15 68 43 62-50-14-16-48 66-53 62 16 14 37-76 64 55 13-17-77-38Z"/><circle cx="114" cy="81" r="6"/><path d="M27 168h170"/></svg><span className="cover-foot">A story worth growing into.</span></div><div className="bookmark-note"><Icon name="leaf" size={18}/><span>Read a little.<br/>Understand a little more.</span></div></div></section>{boot.user&&!boot.user.verified?<Verify compact/>:boot.user&&boot.onboarding.status!=='complete'?<div className="next-step"><div><span className="pill">Your first step</span><h2>Let’s find your starting point</h2><p>Tell us about your Spanish, then try a few short questions. Progress saves automatically.</p></div><LinkButton to="#/placement">{boot.onboarding.status==='in_progress'?'Resume check':'Get started'}<Icon name="arrow" size={18}/></LinkButton></div>:boot.user&&boot.dueReviews>0?<div className="next-step"><div><span className="pill">A little review</span><h2>{boot.dueReviews} saved {boot.dueReviews===1?'word is':'words are'} ready</h2><p>A quick recall check keeps useful vocabulary close for your next reading session.</p></div><LinkButton to="#/reviews">Review words</LinkButton></div>:null}<section className="library-section"><div className="library-heading"><div><h2>Your reading shelf</h2><p>Choose a book. Open a new part of your Spanish.</p></div><a className="text-link" href="#/upload"><Icon name="upload" size={18}/>Add a PDF</a></div>{boot.books.length>3&&<label className="search-label">Find a book<input type="search" value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Title or author"/></label>}<div className="shelf">{books.map((b,i)=><article className="shelf-book" key={b.id}><a className={`mini-cover cover-${i%3}`} href={href('book',b.id)} aria-label={`Open ${b.title}`}><Icon name="book" size={28}/><span>{b.title}</span><small>{b.kind==='upload'?'Your Spanish document':'The complete novel'}</small></a><div className="book-info"><span className="pill subtle">{b.kind==='upload'?'Your PDF':'Start here'}</span><h3><a href={href('book',b.id)}>{b.title}</a></h3><p>{b.author}</p><p className="book-detail">{b.status==='ready'?`${b.chapterCount} chapters · Read at your own pace`:statusLabel(b.status)}</p><div className="actions"><a className="text-link" href={href('reader',b.id)}>{b.position?'Continue reading':'Open reader'}<Icon name="arrow" size={17}/></a><a href={href('book',b.id)}>Study plan</a></div></div></article>)}{!books.length&&<p>No books match. Try a shorter title.</p>}</div></section><section className="learning-strip"><div><span className="step-number">1</span><h3>Start with a passage</h3><p>A story you’re curious about gives every lesson a purpose.</p></div><div><span className="step-number">2</span><h3>Make it make sense</h3><p>Practice useful words and patterns in a short, focused lesson.</p></div><div><span className="step-number">3</span><h3>Return to the story</h3><p>Read with new understanding. Bring what you learn to the next book.</p></div></section></>}
function statusLabel(status){return ({processing:'Extracting your text',needs_confirmation:'Ready to check extracted text',queued:'Waiting to process',running:'Processing',failed:'Processing stopped',cancelled:'Cancelled',ready:'Ready to read',needs_review:'Waiting for content review',pending:'Review pending',complete:'Complete',completed:'Complete'})[status]||status||'Available'}
function Auth({mode='login',token,embedded=false,onDone}){const {refresh,setToast}=useApp();const [error,setError]=useState(''),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);const isRegister=mode==='register',forgot=mode==='forgot',reset=mode==='reset';useEffect(()=>{if(mode==='login'){const notice=sessionStorage.getItem('comelibro:reset-notice');if(notice){setMessage(notice);sessionStorage.removeItem('comelibro:reset-notice')}}},[mode]);const title=isRegister?'Start your next chapter':forgot?'Reset your password':reset?'Choose a new password':'Welcome back';async function submit(e){e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));setBusy(true);setError('');try{if(forgot){const r=await post('/auth/forgot-password',{email:values.email});setMessage(r.message||'If that email has an account, a reset link will arrive shortly.');}else if(reset){await post('/auth/reset-password',{token,password:values.password});sessionStorage.setItem('comelibro:reset-notice','Your password is updated. Sign in with your new password.');history.replaceState(null,'',location.pathname+'#/auth/login');location.reload();}else{const r=await post(isRegister?'/auth/register':'/auth/login',values);await refresh();if(r.email)setToast(r.email.message||'Check your email for a verification link.');if(onDone)onDone();else location.hash=isRegister?'#/verify':'#/';}}catch(e){setError(e.message)}finally{setBusy(false)}}return <section className={embedded?'':'auth-page'} key={mode}>{!embedded&&<><Icon name="leaf" size={32}/><h1>{title}</h1><p>{isRegister?'Build your Spanish around something you want to read.':forgot?'We’ll send a link to the email on your account.':reset?'Use at least 12 characters. A few unrelated words work well.':'Your books, words, and progress are waiting.'}</p></>}<form onSubmit={submit}><Notice error>{error}</Notice><Notice>{message}</Notice>{isRegister&&<label>Your name<input name="name" autoComplete="name" maxLength="80" required/></label>}{!reset&&<label>Email<input type="email" name="email" autoComplete="email" maxLength="254" required autoFocus={embedded}/></label>}{!forgot&&<label>{reset?'New password':'Password'}<input type="password" name="password" autoComplete={isRegister||reset?'new-password':'current-password'} minLength={isRegister||reset?12:1} maxLength="128" required/>{(isRegister||reset)&&<small>12–128 characters. Keep it unique to this account.</small>}</label>}<Button disabled={busy}>{busy?'Please wait…':isRegister?'Create account':forgot?'Send reset link':reset?'Save new password':'Sign in'}</Button></form>{!reset&&<div className="auth-links">{!forgot&&<a href={isRegister?'#/auth/login':'#/auth/register'} onClick={onDone}>{isRegister?'Already registered? Sign in':'New here? Create an account'}</a>}<a href={forgot?'#/auth/login':'#/auth/forgot'} onClick={onDone}>{forgot?'Return to sign in':'Forgot your password?'}</a></div>}{reset&&<div className="auth-links"><a href="#/auth/forgot" onClick={()=>{history.replaceState(null,'',location.pathname+'#/auth/forgot');location.reload()}}>Expired link? Request another</a></div>}</section>}
function Verify({compact=false}){const {boot,refresh}=useApp(),[message,setMessage]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);return <section className={compact?'next-step':'gate'}><div><span className="pill">Check your inbox</span><h2>One more step: verify your email</h2><p>Open the verification link sent to {boot.user?.email}. You can keep reading while you wait.</p>{!boot.capabilities.email&&<Notice>Email delivery is unavailable right now. Try sending again later; your account is saved.</Notice>}<Notice>{message}</Notice><Notice error>{error}</Notice></div><div className="actions"><Button secondary disabled={busy} onClick={async()=>{setBusy(true);setError('');try{const d=await post('/auth/resend-verification');setMessage(d.email.message)}catch(e){setError(e.message)}finally{setBusy(false)}}}>{busy?'Sending…':'Resend verification'}</Button><Button secondary onClick={refresh}>I’ve verified my email</Button></div></section>}
function TokenVerify({token}){const {refresh}=useApp(),[result,setResult]=useState(null),[error,setError]=useState('');const started=useRef(false);useEffect(()=>{if(started.current)return;started.current=true;post('/auth/verify',{token}).then(async r=>{setResult(r);await refresh()}).catch(e=>setError(e.message))},[token]);function leave(path){history.replaceState(null,'',location.pathname+path);location.reload()}return <section className="auth-page">{!result&&!error?<Busy label="Verifying your email…"/>:result?<><Icon name="check" size={40}/><h1>Your email is verified</h1><p>Let’s find a comfortable place to begin reading.</p><Button onClick={()=>leave('#/placement')}>Find my starting point</Button></>:<><h1>This link could not be verified</h1><Notice error>{error}</Notice><Button onClick={()=>leave('#/')}>Return to your account</Button><p>Sign in to request a new verification link.</p></>}</section>}
function Choices({question,value,onChange,disabled=false,autoFocus=false}){const first=useRef(null);useEffect(()=>{if(autoFocus&&!disabled)first.current?.focus()},[question.id,autoFocus,disabled]);return <fieldset className="choices" disabled={disabled}><legend>{question.prompt}</legend>{question.choices.map((choice,i)=><label className={value===i?'selected':''} key={i}><input ref={i===0?first:null} type="radio" name={question.id} checked={value===i} onChange={()=>onChange(i)}/><span className="choice-letter" aria-hidden="true">{String.fromCharCode(65+i)}</span><span>{choice}</span></label>)}</fieldset>}
function Placement(){const {boot,refresh}=useApp(),r=useResource('/placement'),[level,setLevel]=useState(''),[choice,setChoice]=useState(null),[feedback,setFeedback]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState('');const started=useRef(Date.now()),feedbackRef=useRef(null),completionRef=useRef(null);useEffect(()=>{feedbackRef.current?.focus()},[feedback]);useEffect(()=>{if(r.data?.status==='complete'&&!feedback)completionRef.current?.focus()},[r.data?.status,feedback]);if(r.error)return <LoadError error={r.error} retry={r.reload}/>;if(!r.data)return <Busy label="Loading your starting-point check…"/>;const p=r.data;async function start(){setBusy(true);setError('');try{r.setData(await post('/placement/start',{level}));started.current=Date.now()}catch(e){setError(e.message)}finally{setBusy(false)}}async function answer(e){e.preventDefault();if(choice===null)return;setBusy(true);setError('');const key=`${boot.user.id}:placement:${p.question.id}`;try{const d=await post('/placement/answer',attempt(key,{questionId:p.question.id,choiceIndex:choice,elapsedMs:Date.now()-started.current}));setFeedback(d);clearAttempt(key);await refresh()}catch(e){setError(e.message)}finally{setBusy(false)}}return <div className="study-page"><SectionTitle title={p.status==='complete'&&!feedback?'Your starting point':'Find your starting point'}><p>This is a starting point, not a grade. Choose your best answer; it’s fine to be unsure.</p></SectionTitle><Notice error>{error}</Notice>{feedback?<div ref={feedbackRef} tabIndex="-1" className="answer-feedback"><span className={`feedback-symbol ${feedback.correct?'good':''}`}><Icon name={feedback.correct?'check':'book'} size={26}/></span><h2>{feedback.correct?'You’ve got it':'Here’s how it works'}</h2><p>{feedback.explanation}</p><p className="muted">{feedback.scored?'This response helps us choose what to practice.':'Practice recorded. This question did not update a skill estimate.'}</p><Button onClick={()=>{r.setData(feedback.placement);setFeedback(null);setChoice(null);started.current=Date.now()}}>{feedback.placement.status==='complete'?'See my starting point':'Next question'}<Icon name="arrow" size={18}/></Button></div>:p.status==='not_started'?<><div className="level-options" role="radiogroup" aria-label="Your current Spanish">{[['beginner','I’m just beginning','I recognize a few words, but need help with most sentences.'],['elementary','I know the basics','I can understand simple messages and familiar everyday phrases.'],['intermediate','I can follow the main idea','I read everyday Spanish, but longer passages still slow me down.'],['advanced','I’m comfortable with Spanish','I want support with unfamiliar vocabulary and literary language.']].map(([id,label,description])=><label className={level===id?'selected':''} key={id}><input type="radio" name="level" value={id} checked={level===id} onChange={()=>setLevel(id)}/><span><strong>{label}</strong><small>{description}</small></span></label>)}</div><Button disabled={!level||busy} onClick={start}>{busy?'Starting…':'Start the short check'}</Button><p className="muted">Your description guides the check. Only your answers provide learning evidence.</p></>:p.status==='complete'?<><div className="completion"><Icon name="leaf" size={38}/><h2 ref={completionRef} tabIndex="-1">You’re ready for your first passage</h2><p>We’ll use what you demonstrated to choose useful practice. Skills we haven’t checked remain unknown.</p><LinkButton to={href('book','don-quixote')}>Choose my next lesson</LinkButton></div><Evidence objectives={p.objectives}/></>:<><div className="progress-label"><span>Question {p.index+1} of {p.total}</span><span>Your place is saved</span></div><progress value={p.index} max={p.total}/><form onSubmit={answer}><Choices key={p.question.id} question={p.question} value={choice} onChange={setChoice} disabled={busy} autoFocus/><Button disabled={choice===null||busy}>{busy?'Saving answer…':'Check answer'}</Button></form></>}<a className="quiet-link" href={href('reader','don-quixote')}>Read the book anytime</a></div>}
